SELECT role_data_scope_id AS "roleDataScopeId", role_code AS "roleCode", data_scope_type AS "dataScopeType", organization_code AS "organizationCode", work_area AS "workArea" FROM role_data_scope
role_code = #{criteria.roleCode}AND data_scope_type = #{criteria.dataScopeType}AND organization_code = #{criteria.organizationCode}AND work_area = #{criteria.workArea}
ORDER BY role_code, data_scope_type, organization_code, work_area
LIMIT #{criteria.size} OFFSET #{criteria.page}
